  window.LESSONS["u4_l14"] = {"meta":{"grade":4,"subject":"국어","term":1,"unit":4,"unit_title":"뜻을 파악하며 읽어요","n":14,"covers":"14차시","title":"단원 마무리하기","goal":"단원에서 배운 내용을 확인하고, 기초 다지기(된소리 발음·복수 표준어·글씨 쓰기)를 익힌다.","std":"[4국04-02][4국02-02]","duration_min":40,"lesson_format":"단원 마무리 · 2세대 19장(7요소)","theme":"곰이·펭이 낱말 뜻 탐험대","live_url":"../../grade4/semester1/korean/4단원_뜻을파악하며읽어요/g4_kor_u4_l14.html","source":"grade4/semester1/korean/4단원_뜻을파악하며읽어요/g4_kor_u4_l14.html"},"slides":[{"id":"s01","stage":"도입","block":"cover","data":{"title":"단원 마무리하기\n스스로 확인 · 된소리 · 둘 다 맞는 말 · 글씨 쓰기","emoji":"🏁"},"suggested_extras":["v_l8_1"]},{"id":"s02","stage":"도입","block":"review","data":{"title":"지난 시간엔 무엇을 했나요?","content":"지난 시간에는 낱말 하나를 빈칸으로 둔 **알아맞히기 놀이**를 하며 두 뜻이 이어지는지로 **갈래를 가리고**, 「학교 앞에 그늘막이 생겼어요」 기사에서 **중요한 낱말**과 **중심 생각**을 찾아 배운 것이 **생활 속 글**에도 쓰인다는 것을 확인했어요.","items":[{"q":"놀이에서 빈칸 낱말을 맞힌 뒤에 무엇을 더 말하나요?","a":"두 뜻이 이어지는지 살펴 동형이의어인지 다의어인지 말한다"},{"q":"「학교 앞에 그늘막이 생겼어요」 기사의 중요한 낱말은 무엇인가요?","a":"그늘막 · 횡단보도 · 더위"},{"q":"이 기사가 전하려는 생각은 무엇인가요?","a":"더위를 피해 안전하게 신호를 기다리자"}],"from":"u4_l12"},"suggested_extras":["q_l8_1"]},{"id":"s03","stage":"도입","block":"motivate","data":{"scene_title":"늦잠과 국수","kids":[{"face":"🐻","label":"곰이\n\"늦잠 자서 국수를 급하게 먹었어. 읽어 봐, '늦잠' '국수'!\""},{"face":"🐧","label":"펭이\n\"[늗짬], [국쑤]… 어? 글자는 ㅈ·ㅅ 인데 소리는 ㅉ·ㅆ 으로 나네?\""}],"question":"「늦잠」「국수」는 적은 글자와 **소리가 달라요**. 받침 뒤에서 소리가 **세게** 나지요. 오늘은 단원에서 배운 것을 스스로 확인하고, 이런 **소리**와 **둘 다 맞는 말**, 글씨 쓰기까지 함께 다져요.","img":"assets/photo/korean/unit4_finish.jpg","tnote":{"ask":["「늦잠」은 어떻게 소리 나나요?","글자와 소리가 다른 낱말을 또 아나요?"],"watch":"소리 나는 대로 적으려는 경우 — 적는 글자는 그대로, 소리만 달라짐","min":3}},"suggested_extras":["q_l8_2","r_l8_1"]},{"id":"s04","stage":"전개","block":"concept","data":{"fig":{"k":"tools","items":[{"name":"여러 가지로 해석되는 낱말 찾기","emoji":"1️⃣"},{"name":"사전으로 두 갈래 구분하기","emoji":"2️⃣"},{"name":"이야기의 중심 생각 파악하기","emoji":"3️⃣"},{"name":"주장하는 글의 중심 생각 파악하기","emoji":"4️⃣"}]},"title":"이 단원에서 공부한 내용을 살펴봐요","content":"✓여러 가지로 해석되는 낱말을 **찾을** 수 있다\n✓국어사전으로 **동형이의어와 다의어**를 구분할 수 있다\n✓이야기를 읽고 **중심 생각**을 파악할 수 있다\n✓주장하는 글을 읽고 **중심 생각**을 파악할 수 있다","tnote":{"ask":["이 단원에서 배운 네 가지는?","가장 자신 있는 것은 무엇인가요?"],"watch":"네 가지를 섞어 말하는 경우 — 낱말 둘·중심 생각 둘로 묶기","min":4}},"src":11,"suggested_extras":["e_l8_1"]},{"id":"s05","stage":"전개","block":"concept","data":{"fig":{"k":"text","lines":["아침 일찍 **학교**에 갔어요.","비가 와서 우산을 쓰고 **걷다** 보니 신이 젖었어요.","따뜻한 **옷장** 속 외투를 꺼내 **입다**."]},"title":"소리 내어 읽어 봐요","content":"소리 내어 읽어 봐요. **진하게 표시된 낱말**은 받침 뒤 소리가 세게 나요.","tnote":{"ask":["진하게 표시된 낱말을 소리 내어 읽어 봐요.","적은 글자와 소리가 다른 곳은 어디인가요?"],"watch":"「학교」를 [학교]로 읽는 경우 — [학꾜]","min":4}},"src":4,"suggested_extras":["t_l8_1"]},{"id":"s06","stage":"전개","block":"concept","data":{"fig":{"k":"sort2","a":{"name":"자장면 · 삐치다 · 오순도순","items":["이렇게 써도 맞아요"]},"b":{"name":"짜장면 · 삐지다 · 오손도손","items":["이렇게 써도 맞아요"],"hint":"한 가지 뜻을 나타내는 여러 낱말이 **모두 표준어**인 경우도 있어요"}},"title":"둘 다 맞는 말이 있어요","content":"많은 사람이 함께 쓰는 말을 **표준어**라고 해요.\n한 가지 뜻을 나타내는 여러 낱말이\n**모두 표준어**인 경우도 있어요. 🙌","tnote":{"ask":["「자장면」과 「짜장면」 가운데 맞는 말은?","표준어란 무엇인가요?"],"watch":"하나만 맞다고 우기는 경우 — 둘 다 표준어","min":4}},"src":6,"suggested_extras":["e_l8_2","t_l8_2"]},{"id":"s07","stage":"전개","block":"concept","data":{"fig":{"k":"note","title":"문장도 따라 써 봐요","items":["낱말의 뜻을 가려 읽으면","글이 하는 말이 또렷해집니다",{"t":"공책에 또박또박 옮겨 써요","star":true}]},"title":"문장도 따라 써 봐요","content":"\"낱말의 뜻을 **가려 읽으면**\n글이 하는 말이 또렷해집니다.\"\n공책에 또박또박 옮겨 써 보세요. ✏️","tnote":{"ask":["이 문장은 단원의 무엇을 담고 있나요?","또박또박 쓰려면 무엇에 마음을 두나요?"],"watch":"빨리 쓰려고 글자가 흐트러지는 경우 — 한 글자씩","min":4}},"src":9,"suggested_extras":["q_l8_3"]},{"id":"s08","stage":"전개","block":"misconception","data":{"title":"이런 생각을 조심해요","label":"자주 하는 생각","wrong":"「국수」는 **[국쑤]**로 소리 나니 글자도 **「국쑤」**로 적고, 「짜장면」은 **틀린 말**이니 「자장면」만 써야 한다.","right":"소리가 세게 나더라도 적을 때는 **「국수」**처럼 원래 글자대로 적어요. 받침 뒤에서 소리만 **된소리**로 날 뿐이에요. 그리고 많은 사람이 함께 쓰는 말을 **표준어**라고 하는데, 「자장면」과 「짜장면」처럼 한 가지 뜻을 나타내는 여러 낱말이 **모두 표준어**인 경우도 있어요. 둘 다 맞아요.","hint":"「국수」를 칠판에 적고 소리 내어 읽게 한 뒤 「그럼 글자는?」 하고 물어 글자와 소리를 갈라 주세요.","tnote":{"ask":["소리가 센 낱말은 글자도 바꿔 적나요?","「짜장면」은 틀린 말인가요?"],"watch":"소리와 글자를 같은 것으로 여기는 경우 — 읽기와 적기 나누기","min":3}},"suggested_extras":["x_l8_1","x_l8_2"]},{"id":"s09","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ①","scenario":{"icon":"🌳","body":"뜻이 처음 뜻에서 넓어진 느낌이 있으면 다의어예요. 다의어인 짝을 골라요."},"question":"다의어인 것은?","options":[{"text":"산이 높다 / 소리가 높다","correct":true},{"text":"먹는 김 / 오르는 김"},{"text":"묶는 줄 / 서는 줄"}],"note":"풀이: 처음 뜻에서 넓어진 느낌을 찾아요. → **산이 높다 / 소리가 높다**"},"src":2,"suggested_extras":["t_l8_3"]},{"id":"s10","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ②","scenario":{"icon":"🤝","body":"한 가지 뜻을 나타내는 두 낱말이 모두 맞는 말일 때가 있어요. 뜻이 같아 함께 쓸 수 있는 말을 이어요."},"question":"뜻이 같아 함께 쓸 수 있는 말을 이어요","answer":"자장면 ↔ 🍜짜장면 / 삐치다 ↔ 😤삐지다 / 오순도순 ↔ 🏠오손도손","note":"풀이: 소리가 비슷한 짝을 찾아봐요."},"src":7,"suggested_extras":["e_l8_3"]},{"id":"s11","stage":"기본문제","block":"basic_problem","data":{"title":"기본 문제 ③","scenario":{"icon":"🔊","body":"천천히 소리 내어 읽어 봐요. 받침 뒤에서 된소리로 소리 나는 낱말을 **모두** 골라요."},"question":"된소리로 소리 나는 낱말을 모두 찾아요","options":[{"text":"늦잠","correct":true},{"text":"바다"},{"text":"책상","correct":true},{"text":"국수","correct":true}],"multi":true,"note":"풀이: 천천히 소리 내어 읽어 봐요. → 알맞은 것 **3개**"},"src":5,"suggested_extras":["q_l8_4"]},{"id":"s12","stage":"기본문제","block":"leveled_problem","data":{"title":"수준을 골라 풀어요","levels":{"기본":{"q":"「늦잠·바다·책상·국수」를 소리 내어 읽고, 된소리로 소리 나는 낱말과 그 소리를 말해 봐요.","a":"늦잠 [늗짬] · 책상 [책쌍] · 국수 [국쑤] — 바다는 그대로 [바다]","steps":["한 낱말씩 천천히 읽는다","받침 뒤 소리가 세게 나는지 듣는다","소리 나는 대로 말하되 글자는 그대로 둔다"]},"도전":{"q":"이 단원에서 배운 「여러 가지로 해석되는 낱말」과 「중심 생각」이 서로 어떻게 이어지는지 「김」과 「우산 두 개」 글을 들어 말해 봐요.","a":"낱말의 뜻을 알맞게 파악해야 문장이 바로 읽히고, 문장이 바로 읽혀야 글쓴이의 중심 생각이 또렷하게 보인다","steps":["낱말 뜻을 잘못 읽으면 어떻게 되는지 말한다","문장과 중심 생각의 관계를 말한다","둘을 한 문장으로 잇는다"]},"심화":{"q":"여러 가지로 해석되는 낱말로 짧은 시를 쓰거나, 읽고 싶은 글의 중심 생각을 찾아 말해 봐요.","a":"여러 답 (예: 「길」로 두 줄 시 · 학급 문고 책 한 권의 중심 생각)","open":true}},"tnote":{"ask":["기본에서 글자와 소리를 갈라 말했나요?","도전에서 「낱말 → 문장 → 중심 생각」이 이어졌나요?"],"watch":"심화에서 시와 중심 생각 찾기를 둘 다 안 고르는 경우 — 하나는 하기","min":3}},"suggested_extras":["q_l8_5","g_l8_1"]},{"id":"s13","stage":"응용문제","block":"offline_activity","data":{"title":"또박또박 글씨 쓰기","type":"pair","goal":"짝과 「뜻·중심·생각」 세 낱말과 「낱말의 뜻을 가려 읽으면 글이 하는 말이 또렷해집니다」 문장을 칸 공책에 또박또박 옮겨 쓰고, 서로 글씨를 보며 가장 잘 쓴 글자에 동그라미 쳐 주기","steps":["칸 공책을 펴고 세 낱말을 한 글자씩 칸에 맞춰 쓴다","문장을 두 줄로 나누어 옮겨 쓴다","짝과 공책을 바꾸어 가장 잘 쓴 글자에 동그라미를 친다","흐트러진 글자 하나를 골라 다시 쓴다"],"solo":["세 낱말과 문장을 칸 공책에 옮겨 쓴다","가장 잘 쓴 글자와 다시 쓸 글자를 하나씩 고른다"],"materials":["칸 공책","연필","지우개"],"minutes":8,"tnote":{"ask":["가장 잘 쓴 글자는 무엇이었나요?","다시 쓴 글자는 무엇이었나요?"],"watch":"칸을 넘겨 쓰거나 글자 크기가 들쑥날쑥한 경우 — 칸에 맞춰","min":8}},"suggested_extras":["g_l8_2","t_l8_4"]},{"id":"s14","stage":"응용문제","block":"real_world","data":{"title":"식당 차림표","scenario":{"icon":"🍜","body":"식당 차림표에 「짜장면」이라고도, 「자장면」이라고도 적혀 있어요. 둘 다 **표준어**라 어느 쪽도 틀리지 않아요. 또 차림표의 「국수」를 소리 내어 읽으면 [국쑤]지만 글자는 「국수」 그대로지요. 글자와 소리, 둘 다 맞는 말을 알면 **헷갈리지 않아요**."},"content":"글자는 그대로, **소리**는 세게."},"suggested_extras":["r_l8_2","r_l8_3"]},{"id":"s15","stage":"응용문제","block":"advanced_problem","data":{"title":"생각을 넓혀요","context":"펭이는 「산이 높다 / 소리가 높다」가 동형이의어라고 했어요. 「산」과 「소리」가 다르니까요.","challenge":"펭이의 생각이 왜 알맞지 않은지 두 「높다」의 뜻과 뿌리를 들어 말해 봐요.","note":"풀이: 동형이의어인지 다의어인지는 「산」「소리」가 아니라 **같은 글자 「높다」의 두 뜻**으로 가려요. 산이 높은 것은 **위로 멀리** 있다는 뜻이고, 소리가 높은 것은 그 뜻이 **넓어져** 소리가 위로 올라간 느낌이에요. 한 뿌리에서 나온 뜻이라 **다의어**예요.","tnote":{"ask":["가리는 기준은 「산·소리」인가요, 「높다」인가요?","두 「높다」는 한 뿌리인가요?"],"watch":"앞말이 다르면 동형이의어로 여기는 경우 — 같은 글자의 뜻으로","min":3}},"suggested_extras":["t_l8_5"]},{"id":"s16","stage":"정리","block":"exit_ticket","data":{"title":"오늘 확인해요","items":[{"q":"「국수」를 소리 내어 읽으면 어떻게 나고, 글자는 어떻게 적나요?","a":"[국쑤]로 소리 나지만 글자는 「국수」 그대로"},{"q":"「자장면」과 「짜장면」 가운데 표준어는 무엇인가요?","a":"둘 다 표준어"},{"q":"이 단원에서 배운 네 가지는 무엇인가요?","a":"여러 가지로 해석되는 낱말 찾기 · 사전으로 동형이의어와 다의어 구분하기 · 이야기의 중심 생각 · 주장하는 글의 중심 생각"}],"self":["오늘 배운 것을 혼자 설명할 수 있어요","조금 헷갈려요","다시 배우고 싶어요"]},"suggested_extras":[]},{"id":"s17","stage":"정리","block":"summary","data":{"title":"오늘 배운 것","points":["낱말의 뜻을 가려 읽고","글의 중심 생각까지 잡아냈어요.","이제 어떤 글을 만나도","하는 말이 또렷하게 보일 거예요! 🎉👏","곰이는 「국수」를 [국쑤]로 읽고 글자는 그대로 두었고, 펭이는 「낱말의 뜻을 가려 읽으면」 문장을 또박또박 옮겨 썼다."],"arrows":["낱말 뜻 가려 읽기 → 중심 생각 잡기","된소리 · 둘 다 맞는 말 · 또박또박 글씨","다음: 말과 글로 생각을 전해요"]},"suggested_extras":["r_l8_1"]},{"id":"s18","stage":"정리","block":"self_assessment","data":{"title":"스스로 점검해요","items":["📚 지식·이해 — 이 단원에서 배운 네 가지를 말할 수 있나요?","🔧 과정·기능 — 받침 뒤 된소리와 둘 다 맞는 말을 가릴 수 있나요?","💛 가치·태도 — 어떤 글을 만나도 낱말 뜻과 중심 생각을 잡아 볼 마음이 생겼나요?"],"prompts":["이 단원에서 가장 자신 있게 된 것은 무엇인가요?"]},"suggested_extras":["e_l8_3"]},{"id":"s19","stage":"정리","block":"next_lesson","data":{"title":"다음 단원엔","preview":"5단원 「말과 글로 전하는 생각」을 시작해요. 내 생각을 말과 글로 알맞게 전하는 방법을 배워요","emoji":"💬"},"suggested_extras":["c_l8_1"]}],"extras":[{"id":"v_l8_1","type":"video","icon":"🎥","title":"뜻을 파악하며 읽어요 단원 마무리 영상","url":"https://www.youtube.com/results?search_query=%EC%B4%88%EB%93%B1+4%ED%95%99%EB%85%84+%EA%B5%AD%EC%96%B4+%EB%90%9C%EC%86%8C%EB%A6%AC+%EB%B0%9C%EC%9D%8C+%EB%91%98+%EB%8B%A4+%EB%A7%9E%EB%8A%94+%ED%91%9C%EC%A4%80%EC%96%B4+%EC%A7%9C%EC%9E%A5%EB%A9%B4+%EC%9E%90%EC%9E%A5%EB%A9%B4+%EB%8B%A8%EC%9B%90+%EB%A7%88%EB%AC%B4%EB%A6%AC","description":"된소리와 둘 다 맞는 말을 다지는 장면.","source":"유튜브 검색 (교사 사전 확인 권장)","fit_slides":["concept","motivate"]},{"id":"q_l8_1","type":"fun_question","icon":"💡","title":"늦잠","content":"늦잠을 잔 날 어떤 일이 있었나요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_2","type":"fun_question","icon":"💡","title":"국수","content":"「국수」를 소리 내어 읽어 봐요.","fit_slides":["concept","basic_problem"]},{"id":"q_l8_3","type":"fun_question","icon":"💡","title":"짜장면","content":"「짜장면」과 「자장면」 가운데 어느 쪽을 쓰나요?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_4","type":"fun_question","icon":"💡","title":"네 가지","content":"이 단원에서 배운 네 가지 가운데 가장 재미있던 것은?","fit_slides":["concept","basic_problem"]},{"id":"q_l8_5","type":"fun_question","icon":"💡","title":"글씨","content":"또박또박 쓰려면 무엇에 마음을 두나요?","fit_slides":["concept","basic_problem"]},{"id":"t_l8_1","type":"tip","icon":"🧩","title":"소리와 글자 두 칸","content":"칠판에 「글자」「소리」 두 칸을 그려 「국수 / [국쑤]」처럼 나란히 적으세요.","fit_slides":["concept","misconception"]},{"id":"t_l8_2","type":"tip","icon":"🧩","title":"문법 용어 숨기기","content":"「된소리로 소리 나요」「둘 다 맞는 말이에요」로만 말하고 문법 용어는 꺼내지 마세요.","fit_slides":["concept","misconception"]},{"id":"t_l8_3","type":"tip","icon":"🧩","title":"차림표 보기","content":"식당 차림표 사진 한 장이면 둘 다 맞는 말이 바로 보여요.","fit_slides":["concept","misconception"]},{"id":"t_l8_4","type":"tip","icon":"🧩","title":"칸 공책 준비","content":"글씨 쓰기는 칸 공책 한 쪽씩, 짝 바꾸어 보기까지.","fit_slides":["concept","misconception"]},{"id":"t_l8_5","type":"tip","icon":"🧩","title":"다음 예고","content":"다음 단원은 말과 글로 생각을 전하는 공부예요.","fit_slides":["concept","misconception"]},{"id":"r_l8_1","type":"real_world","icon":"🌍","title":"차림표","content":"「짜장면」「자장면」 둘 다 차림표에 있어요.","fit_slides":["real_world","summary"]},{"id":"r_l8_2","type":"real_world","icon":"🌍","title":"이름표","content":"「책상」 이름표를 읽으면 [책쌍]이에요.","fit_slides":["real_world","summary"]},{"id":"r_l8_3","type":"real_world","icon":"🌍","title":"또박또박","content":"안내문은 또박또박 쓴 글씨라 읽기 쉬워요.","fit_slides":["real_world","summary"]},{"id":"g_l8_1","type":"game","icon":"🎮","title":"소리 맞히기","content":"낱말을 보여 주면 소리 나는 대로 가장 빨리 외쳐요.","fit_slides":["leveled_problem","offline_activity"]},{"id":"g_l8_2","type":"game","icon":"🎮","title":"둘 다 맞아?","content":"낱말 짝을 들으면 둘 다 맞으면 ○, 아니면 ✗ 를 들어요.","fit_slides":["leveled_problem","offline_activity"]},{"id":"x_l8_1","type":"misconception","icon":"⚠️","title":"소리대로 적기","content":"[국쑤]로 소리 난다고 「국쑤」로 적는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"x_l8_2","type":"misconception","icon":"⚠️","title":"하나만 맞다","content":"「짜장면」을 틀린 말로 여기는 실수.","fit_slides":["misconception","basic_problem"]},{"id":"e_l8_1","type":"example","icon":"📝","title":"배운 것 네 칸","content":"단원에서 배운 네 가지 카드를 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l8_2","type":"example","icon":"📝","title":"읽기 글 판","content":"「소리 내어 읽어 봐요」 글 판을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"e_l8_3","type":"example","icon":"📝","title":"둘 다 맞는 말","content":"자장면·짜장면 두 통 판을 붙입니다.","fit_slides":["concept","offline_activity"]},{"id":"c_l8_1","type":"checklist","icon":"✅","title":"다음 단원 준비","content":"5단원 「말과 글로 전하는 생각」 — 내 생각을 전할 때 쓸 쪽지와 발표 카드.","fit_slides":["next_lesson"]}]};
